"""F3 port of the Earth4All.jl `Inventory` sector (inventory), generated by audit/t0/e4a_translate.py.

ATTRIBUTION
-----------
Ported from Earth4All.jl (https://github.com/worlddynamics/Earth4All.jl) commit 16f37d013a2f68135f03e7815bf861dbf47311f2, MIT licence,
Copyright (c) 2023 World Dynamics (see NOTICE, licenses/Earth4All.jl-MIT.txt; decisions D-011, D-016, D-018). Equations are from
`src/inventory/subsystems.jl` (function `inventory`; the `*_support` scaffolding systems are not ported),
parameters from `src/inventory/parameters.jl`, initial values from `src/inventory/initialisations.jl`; the number after `L` beside each
equation is its line in `subsystems.jl`. Giant Leap overrides: `src/earth4all/scenarios.jl` `run_gl`. Nothing is taken from
`vensim_source/` or from `VensimOutput/` (D-014). F3 code is Apache 2.0 (D-001).

The reference for the tests is Earth4All.jl itself (D-011, D-018); Earth4All.jl follows Vensim closely for most variables but not for
all, and nothing here claims that the port reproduces Vensim.


Inputs (variables read from other sectors): ORO, TPP.
States (7): DELDI, EPP, INV, PRIN, PRI, RS, SSWI.
"""

from __future__ import annotations

import numpy as np

from f3.sectors.e4a_common import E4ASector, exp, ifelse, log, pulse, ramp, step, withlookup  # noqa: F401

PARAMS = {
    "DAT": 1.2,
    "DDI1980": 1.0,
    "DIC": 0.4,
    "DRI": 1.0,
    "ICPT": 0.25,
    "MRIWI": 1.07,
    "OO": 28087.0,
    "PH": 0.0,
    "PPU": 1.0,
    "SAT": 1.0,
    "INVEODDI": -0.6,
    "INVEOIN": -0.26,
    "INVEOSWI": -0.6,
    "SRI": 1.0,
    "SWI1980": 1.0,
    "TAS": 0.24,
    "I_DELDI": 1.0,
    "I_EPP": 28087.0,
    "I_INV": 11234.8,
    "I_PRIN": 1.0,
    "I_PRI": 1.0,
    "I_RS": 28087.0,
    "I_SSWI": 1.0,
}
PARAMS_GL = {}
PARAM_EXPR = {
}
INITS = {
    "DELDI": 1.0,
    "EPP": 28087.0,
    "INV": 11234.8,
    "PRIN": 1.0,
    "PRI": 1.0,
    "RS": 28087.0,
    "SSWI": 1.0,
}
STATE_NAMES = ("DELDI", "EPP", "INV", "PRIN", "PRI", "RS", "SSWI", )
STATE_INIT = {
    "DELDI": 'I["DELDI"]',
    "EPP": 'I["EPP"]',
    "INV": 'I["INV"]',
    "PRIN": 'I["PRIN"]',
    "PRI": 'I["PRI"]',
    "RS": 'I["RS"]',
    "SSWI": 'I["SSWI"]',
}
INPUT_NAMES = ("ORO", "TPP", )
UNITS = {
    "CDDI": "1/y",
    "CPI": "1/y",
    "DEL": "gu/y",
    "DELDI": "1",
    "DEPU": "1",
    "DSWI": "1",
    "EPP": "gusd/y",
    "GDP": "gusd/y",
    "IC": "y",
    "INV": "gu",
    "IR": "1/y",
    "NI": "gusd/y",
    "ORO": "gu/y",
    "OUTP": "gu/y",
    "PNIS": "1",
    "PRI": "1",
    "PRIN": "1",
    "ROCDDI": "1/y",
    "RS": "gu/y",
    "SA": "gusd/y",
    "SSWI": "1",
    "TPP": "g/y",
}

# algebraic equations (name: expression of the other variables; L = line in subsystems.jl)
EQ = {
    "CDDI": lambda v: v.ROCDDI * v.DELDI,  # L53
    "CPI": lambda v: v.PRIN * v.IR,  # L54
    "DEL": lambda v: ((v.EPP / v.PPU) / (v.DELDI / v.DDI1980)) * ((v.PNIS) if (v.ts > 1984) else (1)),  # L55
    "DEPU": lambda v: 0 + v.PH * pulse(v.ts, 2020, 5),  # L57
    "DSWI": lambda v: 1 + v.INVEOSWI * (v.PRI / v.DRI - 1),  # L58
    "GDP": lambda v: v.OUTP * v.PPU,  # L60
    "IC": lambda v: v.INV / v.RS,  # L61
    "IR": lambda v: v.INVEOIN * (v.PRI / v.MRIWI - 1),  # L63
    "NI": lambda v: v.SA,  # L64
    "OUTP": lambda v: v.ORO * v.SSWI / v.SWI1980,  # L65
    "PNIS": lambda v: 1,  # L67
    "ROCDDI": lambda v: 0 + v.INVEODDI * (v.PRI / v.SRI - 1),  # L69
    "SA": lambda v: v.DEL * v.PPU,  # L71
}

# derivatives of the states (smooth!(x, input, T) is D(x) = (input - x) / T)
DER = {
    "DELDI": lambda v: v.CDDI,  # L56
    "EPP": lambda v: (v.TPP - v.EPP) / (v.DAT),  # L59
    "INV": lambda v: v.OUTP - v.DEL,  # L62
    "PRIN": lambda v: v.CPI,  # L66
    "PRI": lambda v: ((v.IC / v.DIC) - v.PRI) / (v.ICPT),  # L68
    "RS": lambda v: (v.DEL - v.RS) / (v.SAT),  # L70
    "SSWI": lambda v: (v.DSWI - v.SSWI) / (v.TAS),  # L72
}


class InventorySector(E4ASector):
    name = "e4a_inventory"
    SECTOR_KEY = "inventory"
    STATE_NAMES = STATE_NAMES
    PARAMS = PARAMS
    PARAMS_GL = PARAMS_GL
    PARAM_EXPR = PARAM_EXPR
    INITS = INITS
    STATE_INIT = STATE_INIT
    EQ = EQ
    DER = DER
    INPUT_NAMES = INPUT_NAMES
    inputs = {n: UNITS[n] for n in INPUT_NAMES}
    outputs = {n: UNITS[n] for n in list(EQ) + list(STATE_NAMES)}


SECTOR_CLASS = InventorySector
